/** Sets the claim's amount, date and note; a claim given no date takes the sheet's today. */
public class ApplyClaim {
    public void apply(@Val ClaimInput input, @Val Claim claim, SheetRepository sheets) {
        claim.setAmount(input.amount());
        claim.setDate(input.date() != null ? input.date()
                : sheets.findById(claim.getSheetId()).orElseThrow().getToday());
        claim.setNote(input.note());
    }
}
package net.officefloor.hq.app.claim;

/** A claim as shown: its amount with two decimals, its date as yyyy-mm-dd, its status, its number
 *  (null when it has none) and, once settled, its fixed due with two decimals (null while live, or when
 *  no rate applied at settling) and who opened it (null while a draft). */
public record ClaimResponse(long id, long personId, String amount, String date, String note, String status,
        Integer number, String settledDue, String openedBy) {

    public static ClaimResponse from(Claim claim) {
        return new ClaimResponse(claim.getId(), claim.getPersonId(), claim.getAmount().setScale(2).toPlainString(),
                claim.getDate().toString(), claim.getNote(), claim.getStatus().name(), claim.getNumber(),
                claim.getSettledDue() == null ? null : claim.getSettledDue().setScale(2).toPlainString(),
                claim.getOpenedBy());
    }
}
package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.LocalDate;
import java.time.temporal.ChronoUnit;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.rate.RateRepository;
import net.officefloor.hq.app.setting.SettingRepository;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.hq.app.setting.UserRole;
import net.officefloor.hq.app.setting.UserRoleRepository;
import net.officefloor.plugin.variable.Val;
import net.officefloor.web.HttpHeaderParameter;

/** Moves the claim to SETTLED, refusing it when its status does not allow that, and fixes its due at the
 *  rate its person's grade has in force on the claim's date: amount × rate / 100, rounded half up and raised to the sheet's floor (none when no rate applies),
 *  plus, when it is overdue (its date plus the sheet's terms is before the sheet's today), the sheet's late percent of that floored
 *  due for every full 30 days it is overdue, rounded the same way.
 *  The user who opened the claim (arriving as X-User) cannot settle it. A clerk (any user not made a steward)
 *  cannot settle a claim whose due is above the sheet's clerk limit (no limit when none is set; a claim with no due
 *  is within it); a steward settles any. */
public class SettleClaim {
    public void apply(@Val Claim claim, @HttpHeaderParameter("X-User") String user, PersonRepository people,
            RateRepository rates, SettingRepository settings, UserRoleRepository roles, SheetRepository sheets)
            throws InvalidClaimStatusException, SelfSettleException, ClerkLimitException {
        String by = user == null ? "" : user.trim();
        if (claim.getOpenedBy() != null && claim.getOpenedBy().equals(by)) {
            throw new SelfSettleException("The user who opened a claim cannot settle it.");
        }
        ClaimTransition.check(claim.getStatus(), ClaimStatus.SETTLED);
        Person person = people.findById(claim.getPersonId()).orElseThrow();
        BigDecimal due = rates.findInForce(claim.getSheetId(), person.gradeOn(claim.getDate()), claim.getDate())
                .map((r) -> claim.getAmount().multiply(r.getRate())
                        .divide(BigDecimal.valueOf(100), 2, RoundingMode.HALF_UP))
                .orElse(null);
        due = settings.floored(claim.getSheetId(), due);
        if (due != null) {
            LocalDate dueBy = claim.getDate().plusDays(settings.terms(claim.getSheetId()));
            LocalDate today = sheets.findById(claim.getSheetId()).orElseThrow().getToday();
            long spans = dueBy.isBefore(today) ? ChronoUnit.DAYS.between(dueBy, today) / 30 : 0;
            if (spans > 0) {
                due = due.add(due.multiply(settings.latePct(claim.getSheetId())).multiply(BigDecimal.valueOf(spans))
                        .divide(BigDecimal.valueOf(100), 2, RoundingMode.HALF_UP));
            }
        }
        if (due != null && UserRole.CLERK.equals(roles.roleOf(claim.getSheetId(), by))) {
            BigDecimal limit = settings.clerkLimit(claim.getSheetId()).orElse(null);
            if (limit != null && due.compareTo(limit) > 0) {
                throw new ClerkLimitException("A clerk cannot settle a claim whose due is above the clerk limit of "
                        + limit.setScale(2).toPlainString() + ".");
            }
        }
        ClaimTransition.to(claim, ClaimStatus.SETTLED);
        claim.setSettledDue(due);
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.plugin.variable.Val;
import net.officefloor.web.HttpHeaderParameter;

/** Moves the claim to OPEN, refusing it when its status does not allow that, and gives it the sheet's
 *  next number and records who opened it (the signed-in user, arriving as X-User). */
public class OpenClaim {
    public void apply(@Val Claim claim, @HttpHeaderParameter("X-User") String user, ClaimRepository repository) throws InvalidClaimStatusException {
        ClaimTransition.check(claim.getStatus(), ClaimStatus.OPEN);
        // Taking the number holds the sheet's numbers until this change commits or is refused. Then
        // re-check the stored status: an open of the same claim that got there first has committed by
        // now, so this one is refused (and its number rolls back with it).
        repository.takeClaimNumber(claim.getSheetId());
        ClaimTransition.check(ClaimStatus.valueOf(repository.storedStatus(claim.getId())), ClaimStatus.OPEN);
        int number = repository.lastClaimNumber(claim.getSheetId());
        ClaimTransition.to(claim, ClaimStatus.OPEN);
        claim.setNumber(number);
        claim.setOpenedBy(user == null ? "" : user.trim());
    }
}
package net.officefloor.hq.app.claim;

import java.util.List;
import java.util.Optional;
import org.springframework.data.jpa.repository.JpaRepository;
import org.springframework.data.jpa.repository.Modifying;
import org.springframework.data.jpa.repository.Query;
import org.springframework.data.repository.query.Param;

public interface ClaimRepository extends JpaRepository<Claim, Long> {

    /** The sheet's claims, newest first. */
    List<Claim> findBySheetIdOrderByIdDesc(String sheetId);

    Optional<Claim> findByIdAndSheetId(Long id, String sheetId);

    /** Takes the sheet's next claim number. The update locks the sheet's row until the transaction
     *  ends, so claims opened at the same moment are numbered one after the other. */
    @Modifying
    @Query(value = "UPDATE sheet SET claim_numbers = claim_numbers + 1 WHERE id = :sheetId", nativeQuery = true)
    int takeClaimNumber(@Param("sheetId") String sheetId);

    @Query(value = "SELECT claim_numbers FROM sheet WHERE id = :sheetId", nativeQuery = true)
    int lastClaimNumber(@Param("sheetId") String sheetId);

    /** The claim's status as stored now, read past the loaded entity. */
    @Query(value = "SELECT status FROM claim WHERE id = :id", nativeQuery = true)
    String storedStatus(@Param("id") Long id);
}
