package net.officefloor.hq.app.period;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.util.Map;
import java.util.function.Function;
import java.util.stream.Collectors;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.claim.ClaimStatus;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.rate.RateRepository;
import net.officefloor.hq.app.setting.SettingRepository;
import net.officefloor.plugin.variable.Val;

/** Closes the period, refusing one already closed, and fixes its due-total: the due of the claims that
 *  count dated in it (not the OPEN claims of a person on hold), as shown now (a settled claim's fixed due; an open one's at the rate in force on its date for the grade in force on its
 *  date, rounded half to even and raised to the sheet's floor), none where no rate applies. */
public class ClosePeriod {
    public void close(@Val Period period, ClaimRepository claims, PersonRepository people, RateRepository rates,
            SettingRepository settings)
            throws InvalidPeriodException {
        if (period.isClosed()) {
            throw new InvalidPeriodException("The period " + period.getName() + " is already closed.");
        }
        Map<Long, Person> byId = people.findBySheetIdOrderByIdAsc(period.getSheetId()).stream()
                .collect(Collectors.toMap(Person::getId, Function.identity()));
        BigDecimal floor = settings.floor(period.getSheetId());
        BigDecimal total = BigDecimal.ZERO.setScale(2);
        for (Claim c : claims.findBySheetIdOrderByIdDesc(period.getSheetId())) {
            if (!c.getStatus().counts() || !period.contains(c.getDate())
                    || (c.getStatus() == ClaimStatus.OPEN && byId.get(c.getPersonId()).isHeld())) {
                continue;
            }
            BigDecimal due = c.getStatus() == ClaimStatus.SETTLED ? c.getSettledDue()
                    : rates.findInForce(c.getSheetId(), byId.get(c.getPersonId()).gradeOn(c.getDate()), c.getDate())
                            .map((r) -> c.getAmount().multiply(r.getRate())
                                    .divide(BigDecimal.valueOf(100), 2, RoundingMode.HALF_EVEN).max(floor))
                            .orElse(null);
            if (due != null) {
                total = total.add(due);
            }
        }
        period.close(total);
    }
}
import { useState } from 'react';
import type { FormEvent } from 'react';
import { useSubmitOnce } from '../../api/useSubmitOnce';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { HomeMain } from '../../slots/defs/homeMain';
import { useClaimDue, useClaims, useCounts } from '../claims/claims';
import { hundredths, show, usePersonRate } from '../rates/rates';
import { useCurrentSheet, useCurrentUser } from '../session/session';
import { addPeriod, closePeriod, periodsKey, reopenPeriod, usePeriods } from './periods';
import type { Period, PeriodInput } from './periods';

const DATE = /^\d{4}-\d{2}-\d{2}$/;

const EMPTY: PeriodInput = { name: '', from: '', to: '' };

/** A period's due-total in cents: once closed, the one fixed then; otherwise the due of the claims that
 *  count whose date falls in it (n/a as 0). */
function usePeriodDue() {
  const claims = useClaims().data ?? [];
  const rateOf = usePersonRate();
  const counts = useCounts();
  const claimDue = useClaimDue();
  return (period: Period) =>
    period.closed && period.closedTotal !== null
      ? hundredths(period.closedTotal)
      : claims
      .filter((c) => counts(c) && period.from <= c.date && c.date <= period.to)
      .reduce((n, c) => n + (claimDue(c, rateOf(c.personId, c.date)) ?? 0n), 0n);
}

// The sheet's periods: a form that adds one (a name unique on the sheet, from on or before to, not
// overlapping another), and each period with its dates, its due-total, whether it is closed and a button
// that closes it, and one that reopens it (a closed period, by a steward only). A refused close or reopen
// shows on its period.
function Periods() {
  const [sheet] = useCurrentSheet();
  const [user] = useCurrentUser();
  const periods = usePeriods().data ?? [];
  const dueOf = usePeriodDue();
  const [form, setForm] = useState<PeriodInput>(EMPTY);
  const [error, setError] = useState('');
  const queryClient = useQueryClient();
  const once = useSubmitOnce();
  const [periodErrors, setPeriodErrors] = useState<Record<string, string>>({});

  const close = useMutation({
    mutationFn: (name: string) => closePeriod(sheet!, user, name),
    onSuccess: () => queryClient.invalidateQueries({ queryKey: periodsKey(sheet!) }),
    onError: async (_e, name) => {
      setPeriodErrors((e) => ({ ...e, [name]: `The period ${name} could not be closed.` }));
      await queryClient.invalidateQueries({ queryKey: periodsKey(sheet!) });
    },
  });

  const reopen = useMutation({
    mutationFn: (name: string) => reopenPeriod(sheet!, user, name),
    onSuccess: () => queryClient.invalidateQueries({ queryKey: periodsKey(sheet!) }),
    onError: async (_e, name) => {
      setPeriodErrors((e) => ({ ...e, [name]: `The period ${name} could not be reopened: only a steward can reopen a closed period.` }));
      await queryClient.invalidateQueries({ queryKey: periodsKey(sheet!) });
